import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { useAuth } from "../context/AuthContext";
import { api } from "../lib/api";

export default function Dashboard() {
  const { user } = useAuth();
  const [stats, setStats] = useState({ alumni: 0, students: 0, jobs: 0, pending: 0 });
  useEffect(() => {
    (async () => {
      const [a, s, o, r] = await Promise.all([
        api.get("/users?role=alumni"), api.get("/users?role=student"),
        api.get("/opportunities"), api.get("/mentorship/my"),
      ]);
      setStats({ alumni: a.data.length, students: s.data.length, jobs: o.data.length, pending: r.data.filter(x => x.status === "pending").length });
    })();
  }, []);
  return (
    <div style={{ maxWidth: 1200, margin: "0 auto", padding: "3rem 2rem" }}>
      <div className="overline">Dashboard</div>
      <h1 className="font-serif" style={{ fontSize: "3rem", color: "var(--ivy)", margin: "8px 0 2rem" }}>Welcome, {user?.name?.split(" ")[0]}.</h1>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(200px, 1fr))", gap: 16 }}>
        {[
          { label: "Alumni", value: stats.alumni, to: "/directory?role=alumni" },
          { label: "Students", value: stats.students, to: "/directory?role=student" },
          { label: "Opportunities", value: stats.jobs, to: "/jobs" },
          { label: "Pending Requests", value: stats.pending, to: "/mentorship" },
        ].map(s => (
          <Link key={s.label} to={s.to} className="card-editorial" style={{ padding: 24, textDecoration: "none" }}>
            <div className="font-serif" style={{ fontSize: "2.5rem", color: "var(--ivy)" }}>{s.value}</div>
            <div className="overline" style={{ marginTop: 8 }}>{s.label}</div>
          </Link>
        ))}
      </div>
    </div>
  );
}
